class Session05Lab05
{
    public void Run()
    {
        decimal varianceHours = CalculateVariance(8m, 7.5m);
        Console.WriteLine($"Variance: {varianceHours}");
    }

    public decimal CalculateVariance(decimal recordedHours, decimal scheduledHours)
    {
        decimal difference = recordedHours - scheduledHours;
        return difference;
    }
}

class Session05Lab06
{
    public void Run()
    {
        string status = ClassifyVariance(0.5m);
        Console.WriteLine($"Status: {status}");
    }

    public string ClassifyVariance(decimal varianceHours)
    {
        return varianceHours switch
        {
            > 0m => "over schedule",
            < 0m => "under schedule",
            _ => "on schedule"
        };
    }
}

class Session05Lab07
{
    public void Run()
    {
        decimal varianceHours = CalculateVariance(8m, 7.5m);
        string status = ClassifyVariance(varianceHours);
        Console.WriteLine($"Final variance: {varianceHours}; status: {status}");
    }

    public decimal CalculateVariance(decimal recordedHours, decimal scheduledHours)
    {
        return recordedHours - scheduledHours;
    }

    public string ClassifyVariance(decimal varianceHours)
    {
        return varianceHours switch
        {
            > 0m => "over schedule",
            < 0m => "under schedule",
            _ => "on schedule"
        };
    }
}
